export class OfflineRegionEngine{constructor(t={}){this.catalog=t.catalog||[],this.catalogById=new Map(this.catalog.map(t=>[t.id,t]))}getCatalogEntry(t){return this.catalogById.get(t)||null}listRegions(){return[...this.catalog].sort((t,e)=>t.state.localeCompare(e.state))}buildDownloadManifest(t){const e=this.getCatalogEntry(t);if(!e)return null;const o=[{url:e.url,type:"data"}];return e.heroImage&&o.push({url:e.heroImage,type:"image"}),o}getRegionStatus(t,e){const o=this.getCatalogEntry(t);return o?e?e.version===o.version?"downloaded":"update-available":"not-downloaded":"unavailable"}diffForUpdate(t,e){const o=this.buildDownloadManifest(t);if(!o)return null;const a=new Set(o.map(t=>t.url)),n=new Set(e&&e.files||[]);return{toFetch:o.filter(t=>!n.has(t.url)),toRemove:[...n].filter(t=>!a.has(t))}}static formatBytes(t){if(!t||t<=0)return"0 KB";const e=["B","KB","MB","GB"];let o=t,a=0;for(;o>=1024&&a<e.length-1;)o/=1024,a++;const n=0===a?0:o<10?1:0;return`${o.toFixed(n)} ${e[a]}`}static totalStorageUsed(t){return(t||[]).reduce((t,e)=>t+(e.sizeBytes||0),0)}static searchDownloaded(t,e){const o=(t||"").trim().toLowerCase();if(!o)return[];const a=[];for(const[t,n]of Object.entries(e||{}))for(const e of n.destinations||[]){[e.name,e.description,...e.highlights||[]].join(" ").toLowerCase().includes(o)&&a.push({regionId:t,destination:e})}return a}}